use vstd::prelude::*;

verus! {

/// Given a non‐empty vector `x` of i8, returns a length‐2 vector `[min, max]`
/// such that
///  1. `min <= max`,
///  2. every element of `x` lies in `[min, max]`, and
///  3. both `min` and `max` actually occur in `x`.
fn getdomain(x: Vec<i8>) -> (result: Vec<i8>)
    requires
        x.len() > 0,
    ensures
        // result has exactly two elements
        result.len() == 2
        // and they are in non‐decreasing order
        && result.get(0).copied().unwrap() <= result.get(1).copied().unwrap()
        // every element of x is between result[0] and result[1]
        && forall |j: usize| j < x.len() ==>
             result.get(0).copied().unwrap() <= x.get(j).copied().unwrap()
          && x.get(j).copied().unwrap() <= result.get(1).copied().unwrap()
        // result[0] and result[1] both occur somewhere in x
        && exists |j: usize| j < x.len() &&
             x.get(j).copied().unwrap() == result.get(0).copied().unwrap()
        && exists |j: usize| j < x.len() &&
             x.get(j).copied().unwrap() == result.get(1).copied().unwrap(),
{
    let n = x.len();

    // We keep two indices into x: the index of the current min and max.
    let mut min_idx: usize = 0;
    let mut max_idx: usize = 0;
    // We scan from i = 1 up to n.
    let mut i: usize = 1;

    // Invariant summary:
    //   1 <= i <= n,
    //   min_idx < i, max_idx < i,
    //   for all j < i, x[min_idx] <= x[j] <= x[max_idx].
    while i < n
        invariant
            1 <= i && i <= n,
            min_idx < i && max_idx < i,
            forall |j: usize| j < i ==>
                x.get(min_idx).copied().unwrap() <= x.get(j).copied().unwrap()
             && x.get(j).copied().unwrap() <= x.get(max_idx).copied().unwrap(),
        decreases
            n - i,
    {
        let xi  = x.get(i).copied().unwrap();
        let xmn = x.get(min_idx).copied().unwrap();
        let xmx = x.get(max_idx).copied().unwrap();

        if xi < xmn {
            min_idx = i;
        }
        if xi > xmx {
            max_idx = i;
        }
        i += 1;
    }

    // At this point i == n, and min_idx, max_idx < n satisfy that
    // x[min_idx] is the minimum of x[0..n] and x[max_idx] is the maximum.
    let lo = x.get(min_idx).copied().unwrap();
    let hi = x.get(max_idx).copied().unwrap();

    // Build the result vector [lo, hi].
    let mut res: Vec<i8> = Vec::new();
    res.push(lo);
    res.push(hi);
    res
}

} // end verus!

